use derive_more::{Constructor, Display, From};
use rustrade_execution::order::request::{
    CancelThenOpen, OrderRequestAmend, OrderRequestCancel, OrderRequestOpen, RequestOpen,
};
use rustrade_instrument::{exchange::ExchangeIndex, instrument::InstrumentIndex};
use serde::{Deserialize, Serialize};
use std::{fmt::Debug, hash::Hash, marker::PhantomData};

/// RiskManager checks and utilities.
pub mod check;

/// RiskManager interface that reviews and optionally filters cancel and open order requests
/// generated by an [`AlgoStrategy`](super::strategy::algo::AlgoStrategy).
///
/// For example, a RiskManager implementation may wish to:
/// - Filter out orders that would result in too much exposure.
/// - Filter out orders that have a too high quantity.
/// - Adjust order quantities.
/// - Filter out orders that would cross the OrderBook.
/// - etc.
///
/// # Type Parameters
/// * `ExchangeKey` - Type used to identify an exchange (defaults to [`ExchangeIndex`]).
/// * `InstrumentKey` - Type used to identify an instrument (defaults to [`InstrumentIndex`]).
pub trait RiskManager<ExchangeKey = ExchangeIndex, InstrumentKey = InstrumentIndex> {
    /// State used by the `RiskManager` to check the open and cancel requests.
    ///
    /// For a risk manager run by the [`Engine`](crate::engine::Engine), this is the full
    /// `EngineState` of the trading system.
    ///
    /// eg/ `EngineState<DefaultGlobalData, DefaultInstrumentMarketData>`
    type State;

    /// Reviews one batch of the order requests an
    /// [`AlgoStrategy`](super::strategy::algo::AlgoStrategy) generated, returning each as approved
    /// or refused: approved cancels, approved opens, refused cancels, refused opens.
    ///
    /// The [`Engine`](crate::engine::Engine) calls it after each event it processes, except a
    /// contract expiry or a corporate action, while trading is enabled and no drain is in
    /// progress, with the batch its strategy generated from `state`.
    /// It sends only the approved requests, cancels first, and reports the refused ones, with
    /// their reasons, in [`GenerateAlgoOrdersOutput`]. The strategy's
    /// [`CancelThenOpen`] groups are reviewed apart, by
    /// [`check_cancel_then_opens`](Self::check_cancel_then_opens). Commands to close positions or cancel
    /// orders do not pass through it.
    ///
    /// # Caller obligations
    /// - **Return each request once, approved or refused.** The engine does not check this: a
    ///   request in neither output is neither sent nor reported, and one in both is sent and
    ///   reported as refused.
    /// - **An approved request is sent as returned**, so a check that adjusts one, such as
    ///   reducing its quantity, returns the adjusted request.
    /// - **A refusal is final for this batch.** A refused request is not retried, and no refusal
    ///   stops the engine or disables trading. To stop the strategy generating orders, send
    ///   [`TradingState::Disabled`](crate::engine::state::trading::TradingState::Disabled), for
    ///   example with [`System::trading_state`](crate::system::System::trading_state).
    ///
    /// The engine collects all four outputs before it sends anything, so they may borrow `state`.
    ///
    /// [`GenerateAlgoOrdersOutput`]: crate::engine::action::generate_algo_orders::GenerateAlgoOrdersOutput
    fn check(
        &self,
        state: &Self::State,
        cancels: impl IntoIterator<Item = OrderRequestCancel<ExchangeKey, InstrumentKey>>,
        opens: impl IntoIterator<Item = OrderRequestOpen<ExchangeKey, InstrumentKey>>,
    ) -> (
        impl IntoIterator<Item = RiskApproved<OrderRequestCancel<ExchangeKey, InstrumentKey>>>,
        impl IntoIterator<Item = RiskApproved<OrderRequestOpen<ExchangeKey, InstrumentKey>>>,
        impl IntoIterator<Item = RiskRefused<OrderRequestCancel<ExchangeKey, InstrumentKey>>>,
        impl IntoIterator<Item = RiskRefused<OrderRequestOpen<ExchangeKey, InstrumentKey>>>,
    );

    /// Reviews the [`CancelThenOpen`] groups an
    /// [`AlgoStrategy`](super::strategy::algo::AlgoStrategy) generated, approving or refusing
    /// each group whole: approved groups, refused groups.
    ///
    /// The [`Engine`](crate::engine::Engine) calls it right after [`check`](Self::check), on the
    /// same occasions, with the groups from
    /// [`generate_cancel_then_opens`](super::strategy::algo::AlgoStrategy::generate_cancel_then_opens).
    /// It sends the approved groups and reports the refused ones. The caller obligations of
    /// [`check`](Self::check) apply to each group: return it once, approved or refused; an
    /// approved group is sent as returned; a refusal is final for this batch.
    ///
    /// # Default
    /// Passes each group's legs, alone, through [`check`](Self::check). A group is approved, with
    /// the legs as `check` returned them, only if `check` refused none of them; otherwise it is
    /// refused whole, as the strategy generated it, with the refused legs' reasons. So a risk manager written before groups
    /// existed reviews their legs too. `check` sees each group as a batch of its own, so a check
    /// that weighs a whole batch, such as total exposure, sees a group apart from the requests
    /// that [`check`](Self::check) reviewed. Override this to review groups together with them.
    fn check_cancel_then_opens(
        &self,
        state: &Self::State,
        groups: impl IntoIterator<Item = CancelThenOpen<ExchangeKey, InstrumentKey>>,
    ) -> (
        impl IntoIterator<Item = RiskApproved<CancelThenOpen<ExchangeKey, InstrumentKey>>>,
        impl IntoIterator<Item = RiskRefused<CancelThenOpen<ExchangeKey, InstrumentKey>>>,
    )
    where
        ExchangeKey: Debug + Clone,
        InstrumentKey: Debug + Clone,
    {
        let mut approved = Vec::new();
        let mut refused = Vec::new();
        for group in groups {
            let on_cancel_failure = group.on_cancel_failure;
            // Kept to report a refusal with: `check` takes the legs by value.
            let generated = group.clone();
            let CancelThenOpen { cancels, opens, .. } = group;
            let (cancels, opens, refused_cancels, refused_opens) =
                self.check(state, cancels, opens);
            let cancels: Vec<_> = cancels.into_iter().map(RiskApproved::into_item).collect();
            let opens: Vec<_> = opens.into_iter().map(RiskApproved::into_item).collect();
            let reasons: Vec<String> = refused_cancels
                .into_iter()
                .map(|refused| format!("cancel {:?}: {}", refused.item.key, refused.reason))
                .chain(
                    refused_opens
                        .into_iter()
                        .map(|refused| format!("open {:?}: {}", refused.item.key, refused.reason)),
                )
                .collect();
            if reasons.is_empty() {
                approved.push(RiskApproved::new(
                    CancelThenOpen::new(cancels, opens).with_on_cancel_failure(on_cancel_failure),
                ));
            } else {
                refused.push(RiskRefused::new(generated, reasons.join("; ")));
            }
        }
        (approved, refused)
    }

    /// Reviews the amends an [`AlgoStrategy`](super::strategy::algo::AlgoStrategy) generated,
    /// approving or refusing each: approved amends, refused amends.
    ///
    /// The [`Engine`](crate::engine::Engine) calls it right after
    /// [`check_cancel_then_opens`](Self::check_cancel_then_opens), on the same occasions, with the
    /// amends from
    /// [`generate_amends`](super::strategy::algo::AlgoStrategy::generate_amends) as it built them
    /// from the orders it tracks: each carries the order as it stands
    /// ([`RequestAmend::current`](rustrade_execution::order::amend::RequestAmend::current)) and
    /// the quantity filled. The caller obligations of [`check`](Self::check) apply: return each
    /// amend once, approved or refused; an approved amend is sent as returned.
    ///
    /// # Default
    /// Approves an amend that only lowers the quantity, since it cannot add exposure. Every
    /// other amend is passed through [`check`](Self::check) as the open it would leave resting:
    /// the amended order, for the quantity left to fill. The amend is approved if `check` approves
    /// that open unchanged, and refused otherwise, with `check`'s reason, or because `check`
    /// adjusted it: an amend cannot be sent as adjusted.
    ///
    /// `check` sees the projected open on top of the state, which still holds the order before
    /// the amend. A check that sums the exposure of resting orders therefore counts the order
    /// twice. Override this to net it out.
    fn check_amends(
        &self,
        state: &Self::State,
        amends: impl IntoIterator<Item = OrderRequestAmend<ExchangeKey, InstrumentKey>>,
    ) -> (
        impl IntoIterator<Item = RiskApproved<OrderRequestAmend<ExchangeKey, InstrumentKey>>>,
        impl IntoIterator<Item = RiskRefused<OrderRequestAmend<ExchangeKey, InstrumentKey>>>,
    )
    where
        ExchangeKey: Debug + Clone,
        InstrumentKey: Debug + Clone,
    {
        let mut approved = Vec::new();
        let mut refused = Vec::new();
        for amend in amends {
            let request = &amend.state;
            let amended = match request.amended() {
                Ok(amended) => amended,
                Err(refusal) => {
                    refused.push(RiskRefused::new(amend, refusal.to_string()));
                    continue;
                }
            };

            let lowers_quantity_only = request.patch.price.is_none()
                && request.patch.trigger_price.is_none()
                && request
                    .patch
                    .quantity
                    .is_some_and(|quantity| quantity < request.current.quantity);
            if lowers_quantity_only {
                approved.push(RiskApproved::new(amend));
                continue;
            }

            let projected = RequestOpen::new(
                amended.side,
                amended.price,
                amended.quantity - request.filled,
                amended.kind,
                amended.time_in_force,
            )
            .with_reduce_only(amended.reduce_only);
            let open = OrderRequestOpen {
                key: amend.key.clone(),
                state: projected.clone(),
            };
            let (_, opens, _, refused_opens) = self.check(state, std::iter::empty(), [open]);
            let opens: Vec<_> = opens.into_iter().map(RiskApproved::into_item).collect();
            let reasons: Vec<String> = refused_opens
                .into_iter()
                .map(|refused| refused.reason)
                .collect();
            match (opens.as_slice(), reasons.is_empty()) {
                ([open], true) if open.state == projected => {
                    approved.push(RiskApproved::new(amend));
                }
                (_, false) => refused.push(RiskRefused::new(amend, reasons.join("; "))),
                (opens, true) => refused.push(RiskRefused::new(
                    amend,
                    format!("the risk manager adjusted the order the amend leaves: {opens:?}"),
                )),
            }
        }
        (approved, refused)
    }
}

/// New type that wraps order requests that have passed [`RiskManager`] checks.
#[derive(
    Debug,
    Clone,
    Eq,
    PartialEq,
    Ord,
    PartialOrd,
    Hash,
    Deserialize,
    Serialize,
    Display,
    From,
    Constructor,
)]
pub struct RiskApproved<T>(pub T);

impl<T> RiskApproved<T> {
    pub fn into_item(self) -> T {
        self.0
    }
}

/// An order request a [`RiskManager`] refused, and why.
///
/// A refusal concerns that one request only: the engine does not send it, reports it, and carries
/// on. See [`RiskManager::check`].
#[derive(Debug, Clone, Eq, PartialEq, Ord, PartialOrd, Hash, Deserialize, Serialize)]
pub struct RiskRefused<T> {
    /// The refused request.
    pub item: T,
    /// Why it was refused.
    pub reason: String,
}

impl<T> RiskRefused<T> {
    pub fn new(item: T, reason: impl Into<String>) -> Self {
        Self {
            item,
            reason: reason.into(),
        }
    }

    pub fn into_item(self) -> T {
        self.item
    }
}

/// Naive implementation of the [`RiskManager`] interface, approving all orders *without any
/// risk checks*.
///
/// *THIS IS FOR DEMONSTRATION PURPOSES ONLY, NEVER USE FOR REAL TRADING OR IN PRODUCTION*.
#[derive(Debug, Clone)]
pub struct DefaultRiskManager<State> {
    phantom: PhantomData<State>,
}

impl<State> Default for DefaultRiskManager<State> {
    fn default() -> Self {
        Self {
            phantom: PhantomData,
        }
    }
}

impl<State, ExchangeKey, InstrumentKey> RiskManager<ExchangeKey, InstrumentKey>
    for DefaultRiskManager<State>
{
    type State = State;

    fn check(
        &self,
        _: &Self::State,
        cancels: impl IntoIterator<Item = OrderRequestCancel<ExchangeKey, InstrumentKey>>,
        opens: impl IntoIterator<Item = OrderRequestOpen<ExchangeKey, InstrumentKey>>,
    ) -> (
        impl IntoIterator<Item = RiskApproved<OrderRequestCancel<ExchangeKey, InstrumentKey>>>,
        impl IntoIterator<Item = RiskApproved<OrderRequestOpen<ExchangeKey, InstrumentKey>>>,
        impl IntoIterator<Item = RiskRefused<OrderRequestCancel<ExchangeKey, InstrumentKey>>>,
        impl IntoIterator<Item = RiskRefused<OrderRequestOpen<ExchangeKey, InstrumentKey>>>,
    ) {
        (
            cancels.into_iter().map(RiskApproved::new),
            opens.into_iter().map(RiskApproved::new),
            std::iter::empty(),
            std::iter::empty(),
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use rust_decimal::Decimal;
    use rust_decimal_macros::dec;
    use rustrade_execution::order::{
        OrderKey, OrderKind, TimeInForce,
        amend::{AmendPatch, AmendTarget, RequestAmend},
        id::{ClientOrderId, OrderId, StrategyId, VenueOrderId},
        request::{OnCancelFailure, ReduceOnly, RequestCancel, RequestOpen},
    };
    use rustrade_instrument::Side;

    /// Refuses an open above 10, cuts one above 1 down to 1, and approves the rest.
    struct SizeCap;

    impl RiskManager for SizeCap {
        type State = ();

        fn check(
            &self,
            _: &Self::State,
            cancels: impl IntoIterator<Item = OrderRequestCancel>,
            opens: impl IntoIterator<Item = OrderRequestOpen>,
        ) -> (
            impl IntoIterator<Item = RiskApproved<OrderRequestCancel>>,
            impl IntoIterator<Item = RiskApproved<OrderRequestOpen>>,
            impl IntoIterator<Item = RiskRefused<OrderRequestCancel>>,
            impl IntoIterator<Item = RiskRefused<OrderRequestOpen>>,
        ) {
            let (mut approved, mut refused) = (Vec::new(), Vec::new());
            for mut open in opens {
                if open.state.quantity > dec!(10) {
                    refused.push(RiskRefused::new(open, "too large"));
                } else {
                    open.state.quantity = open.state.quantity.min(dec!(1));
                    approved.push(RiskApproved::new(open));
                }
            }
            (
                cancels.into_iter().map(RiskApproved::new),
                approved,
                std::iter::empty(),
                refused,
            )
        }
    }

    fn key(cid: &str) -> OrderKey {
        OrderKey {
            exchange: ExchangeIndex(0),
            instrument: InstrumentIndex(0),
            strategy: StrategyId::new("test"),
            cid: ClientOrderId::new(cid),
        }
    }

    fn open(cid: &str, quantity: Decimal) -> OrderRequestOpen {
        OrderRequestOpen {
            key: key(cid),
            state: RequestOpen::new(
                Side::Sell,
                None,
                quantity,
                OrderKind::Market,
                TimeInForce::ImmediateOrCancel,
            ),
        }
    }

    fn group(opens: Vec<OrderRequestOpen>) -> CancelThenOpen {
        CancelThenOpen::new(
            vec![OrderRequestCancel {
                key: key("stop"),
                state: RequestCancel { id: None },
            }],
            opens,
        )
    }

    /// By default each group's legs pass through `check` alone: a group is approved with its legs
    /// as `check` returned them and its failure policy kept, or refused whole, as generated, when
    /// `check` refuses any leg.
    #[test]
    fn the_default_group_check_approves_or_refuses_each_group_whole() {
        let untouched = group(vec![open("small", dec!(0.5))]);
        let cut =
            group(vec![open("medium", dec!(5))]).with_on_cancel_failure(OnCancelFailure::SendOpens);
        let refused = group(vec![open("small", dec!(0.5)), open("large", dec!(20))]);

        let (approved, refusals) =
            SizeCap.check_cancel_then_opens(&(), [untouched.clone(), cut.clone(), refused.clone()]);
        let approved: Vec<_> = approved.into_iter().map(RiskApproved::into_item).collect();
        let refusals: Vec<_> = refusals.into_iter().collect();

        let mut cut_down = cut;
        cut_down.opens[0].state.quantity = dec!(1);
        assert_eq!(approved, vec![untouched, cut_down]);
        assert_eq!(refusals.len(), 1, "{refusals:?}");
        assert_eq!(refusals[0].item, refused, "refused as generated");
        assert_eq!(
            refusals[0].reason,
            format!("open {:?}: too large", key("large"))
        );
    }

    fn amend(
        cid: &str,
        quantity: Decimal,
        filled: Decimal,
        patch: AmendPatch,
    ) -> OrderRequestAmend {
        OrderRequestAmend {
            key: key(cid),
            state: RequestAmend::new(
                VenueOrderId::Assigned(OrderId::new(cid)),
                patch,
                AmendTarget {
                    side: Side::Buy,
                    price: Some(dec!(100)),
                    quantity,
                    kind: OrderKind::Limit,
                    time_in_force: TimeInForce::GoodUntilCancelled { post_only: false },
                    reduce_only: ReduceOnly::No,
                },
                filled,
            ),
        }
    }

    /// By default an amend that only lowers the quantity is approved unchecked, and any other is
    /// checked as the open it leaves resting: the amended order, for what is left to fill.
    /// Approved only if `check` approves that open unchanged.
    #[test]
    fn the_default_amend_check_reviews_the_order_the_amend_leaves() {
        let reprice = AmendPatch::default().with_price(dec!(99));
        let small = amend("small", dec!(0.5), dec!(0), reprice);
        let mostly_filled = amend("mostly_filled", dec!(5), dec!(4.5), reprice);
        let cut = amend("cut", dec!(5), dec!(0), reprice);
        let large = amend("large", dec!(20), dec!(0), reprice);
        let lowered = amend(
            "lowered",
            dec!(20),
            dec!(0),
            AmendPatch::default().with_quantity(dec!(15)),
        );

        let (approved, refusals) = SizeCap.check_amends(
            &(),
            [
                small.clone(),
                mostly_filled.clone(),
                cut.clone(),
                large.clone(),
                lowered.clone(),
            ],
        );
        let approved: Vec<_> = approved.into_iter().map(RiskApproved::into_item).collect();
        let refusals: Vec<_> = refusals.into_iter().collect();

        assert_eq!(approved, vec![small, mostly_filled, lowered]);
        assert_eq!(refusals.len(), 2, "{refusals:?}");
        assert_eq!(refusals[0].item, cut);
        assert!(
            refusals[0].reason.starts_with("the risk manager adjusted"),
            "{}",
            refusals[0].reason
        );
        assert_eq!(refusals[1].item, large);
        assert_eq!(refusals[1].reason, "too large");
    }

    /// Only an amend that changes the quantity alone, lowering it, skips `check`: a quantity
    /// raised, or lowered beside a new price or trigger, is checked as the open it leaves.
    #[test]
    fn the_default_amend_check_skips_only_a_quantity_lowered_alone() {
        let raised = amend(
            "raised",
            dec!(5),
            dec!(0),
            AmendPatch::default().with_quantity(dec!(20)),
        );
        let lowered_and_repriced = amend(
            "lowered_and_repriced",
            dec!(30),
            dec!(0),
            AmendPatch::default()
                .with_quantity(dec!(20))
                .with_price(dec!(99)),
        );

        let (approved, refusals) =
            SizeCap.check_amends(&(), [raised.clone(), lowered_and_repriced.clone()]);
        assert_eq!(approved.into_iter().count(), 0);
        let refused: Vec<_> = refusals.into_iter().map(|refusal| refusal.item).collect();
        assert_eq!(refused, vec![raised, lowered_and_repriced]);
    }
}
